<script setup lang="ts">
import { computed,ref } from 'vue'
import { frameUrl } from '@/api/endpoints'
import { useCleanStore } from '@/stores/clean'
const store=useCleanStore(),limit=ref(24),failed=ref(new Set<string>()),loaded=ref(new Set<string>())
const names:Record<string,string>={dedup:'重复候选',blur:'清晰度不足',crop:'裁切',rotate:'旋转',mirror:'镜像'}
const sample=computed(()=>store.hitList.slice(0,limit.value))
const basename=(uri:string)=>uri.split(/[\\/]/).pop()||uri
</script>
<template><section class="preview" aria-label="清洗预览"><header><div><span class="step">03</span><h2>先检查，再决定是否整理</h2></div><button class="check" :disabled="!store.hasSelection||!store.scope.length||store.previewing||store.applying" @click="store.runPreview">{{store.previewing?'正在检查…':'检查这批图片'}}</button></header>
<p v-if="!store.hasSelection" class="empty">在左侧选择重复或模糊检查。系统会先给出候选，不会直接移除图片。</p><p v-else-if="store.previewing" class="empty" role="status">正在检查 {{store.scope.length}} 张图片，请稍候。图片数量越多，检查时间越长。</p><p v-else-if="store.previewError" class="failure" role="alert">检查失败：{{store.previewError}} <button @click="store.runPreview">重新检查</button></p><p v-else-if="!store.previewFresh" class="empty">检查项、参数或处理范围已准备好。点击「检查这批图片」查看实际结果。</p>
<template v-else><div class="summary"><div><b>{{store.stat.total}}</b><span>已检查</span></div><div><b>{{store.stat.kept}}</b><span>将在新版本保留</span></div><div class="candidate"><b>{{store.stat.removed}}</b><span>候选排除图片</span></div></div><p class="hint">以下图片将在确认后从输出版本排除。原文件和输入版本仍保留。相邻太阳观测可能高度相似，请谨慎核对。</p><p v-if="!store.hitList.length" class="empty">没有发现符合当前条件的排除项。{{store.stat.transforms?'本次包含图像变换，确认后将生成派生图片。':'可调整标准重新检查，或继续下一步。'}}</p>
<div class="candidates"><article v-for="(item,i) in sample" :key="item.uri"><div class="candidate-image"><span v-if="!loaded.has(item.uri)&&!failed.has(item.uri)" class="image-status">正在载入候选图…</span><img v-if="!failed.has(item.uri)" :src="frameUrl(item.uri,{width:240,height:160})" :alt="basename(item.uri)" loading="lazy" @load="loaded.add(item.uri)" @error="failed.add(item.uri)"/><span v-else class="unavailable">图片暂时无法预览 <button @click="failed.delete(item.uri)">重试</button></span></div><div><small>#{{i+1}} · {{names[item.op]||item.op}}</small><b :title="item.uri">{{basename(item.uri)}}</b><p>{{item.reason}}</p></div></article></div><button v-if="sample.length<store.hitList.length" @click="limit+=24">继续显示（共 {{store.hitList.length}} 张候选）</button></template>
</section></template>
<style scoped>
.preview{flex:1;min-width:0;overflow:auto;padding:20px 24px}.preview header{display:flex;align-items:center;justify-content:space-between;gap:15px;flex-wrap:wrap}.preview header>div{display:flex;gap:10px;align-items:center}.preview h2{font-size:16px;margin:0}.step{color:var(--accent);font:16px Consolas,monospace}.preview button{border:1px solid var(--border);background:var(--bg-panel);color:var(--text-primary);padding:9px 14px;border-radius:5px;cursor:pointer}.preview .check{background:var(--accent);color:var(--bg-base);border-color:var(--accent);font-weight:600}.preview button:disabled{opacity:.4;cursor:default}.empty{padding:35px 20px;line-height:1.9;color:var(--text-muted);font-size:13px;border:1px dashed var(--border);border-radius:8px;margin-top:20px}.failure{color:var(--danger);line-height:1.8}.summary{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin:24px 0 12px}.summary>div{border:1px solid var(--border);border-radius:7px;background:var(--bg-panel);padding:15px}.summary b{display:block;font:26px Consolas,monospace;margin-bottom:7px}.summary span{color:var(--text-muted);font-size:11px}.summary .candidate b{color:var(--warning)}.hint{color:var(--text-secondary);font-size:11px;line-height:1.8}.candidates{display:grid;grid-template-columns:repeat(auto-fill,minmax(205px,1fr));gap:12px}.candidates article{border:1px solid var(--border);background:var(--bg-panel);border-radius:6px;overflow:hidden}.candidate-image{position:relative}.image-status{position:absolute;inset:0;display:grid;place-items:center;font-size:11px;color:var(--text-muted);background:#050a10}.candidates img,.unavailable{width:100%;height:140px;object-fit:contain;background:#050a10;display:block}.candidates article>div{padding:10px}.candidates small{color:var(--warning);font-size:10px}.candidates b{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;margin-top:7px;font-size:11px}.candidates p{color:var(--text-muted);font-size:11px;line-height:1.7}
</style>
